import re


def slugify(text):
    """Turn a title into a URL slug."""
    text = text.lower()
    text = re.sub(r"[^a-z0-9]+", "-", text)
    return text


def word_count(text):
    return len(text.split())

from textutils import slugify, word_count


def test_basic_slug():
    assert slugify("Hello, World!") == "hello-world"


def test_word_count():
    assert word_count("a b  c") == 3

