def test_slugify_no_leading_trailing_hyphens():
    assert slugify("  --Hello--  ") == "hello"
    assert slugify("-hello-") == "hello"


def test_slugify_empty_or_no_alphanumeric():
    assert slugify("") == ""
    assert slugify("!!!") == ""
    assert slugify("   ") == ""


def test_slugify_max_length():
